mkdir -p /tmp/recon && cat > /tmp/recon/run.py <<'EOF'
import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
B="http://localhost:8080"
tok=[None]
def newtok():
    while True:
        try:
            r=urllib.request.Request(B+"/token",method="POST")
            tok[0]=json.load(urllib.request.urlopen(r,timeout=10))["token"]; return
        except Exception as e:
            time.sleep(1)
def get(path):
    if not tok[0]: newtok()
    for attempt in range(200):
        try:
            r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok[0]})
            return json.load(urllib.request.urlopen(r,timeout=10))
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==429:
                ra=float(e.headers.get("Retry-After") or 1); time.sleep(ra)
            elif e.code==401:
                newtok()
            elif e.code==404:
                return None
            else:
                print("HTTP",e.code,path,body[:100]); time.sleep(1)
        except Exception as e:
            print("ERR",path,e); time.sleep(1)
    raise SystemExit("gave up "+path)
orders=[]; page=1; tp=None
while True:
    d=get(f"/orders?page={page}")
    tp=d["total_pages"]; orders+=d["items"]
    if not d["next"]: break
    page+=1
print("pages",page,tp,"rows",len(orders))
seen={}; dups=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: print("DIFFERING DUP",o,seen[o["id"]])
    else: seen[o["id"]]=o
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
q=[o for o in seen.values() if o["status"]=="shipped" and lo<=datetime.fromisoformat(o["placed_at"]).astimezone(timezone.utc)<hi]
print("distinct",len(seen),"qualifying",len(q), "statuses",sorted({o["status"] for o in orders}))
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
missing=[c for c,v in cust.items() if v is None]
print("customers",len(cust),"missing",missing)
reg={"north":0,"south":0,"east":0,"west":0}; tot=0
for o in q:
    c=cust[o["customer_id"]]
    if c is None: continue
    n=o["amount_cents"]*(100-c["discount_pct"])
    v=(n+50)//100
    reg[c["region"]]+=v; tot+=v
res={"total_cents":tot,"order_count":len(q),"duplicates_skipped":dups,"by_region":reg}
print(res)
json.dump(res,open("/workspace/result.json","w"),indent=2)
EOF
python3 -I /tmp/recon/run.py

